package at.co.svc.agate.core.dsl.register;

import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Evaluates ONLY the single- and two-clause exception conditions generated by the
 * TestSOAP-to-AGATE migration. All other conditions remain with the existing
 * JEXL evaluator. The original CSV values are checked to avoid interpreting
 * unrelated expressions as migration-specific conditions.
 */
final class MigratedSoapExceptionCondition {
    private static final Pattern SINGLE_CONDITION = Pattern.compile(
            "^\\s*'([^']*)'\\s*(==|!=)\\s*'(?:NULL|\\{NULL\\})'\\s*$",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern GENERATED_CONDITION = Pattern.compile(
            "^\\s*'([^']*)'\\s*(==|!=)\\s*'(?:NULL|\\{NULL\\})'"
            + "\\s*&&\\s*'([^']*)'\\s*(==|!=)\\s*'(?:NULL|\\{NULL\\})'\\s*$",
            Pattern.CASE_INSENSITIVE);

    private MigratedSoapExceptionCondition() { }

    /** Returns null when the condition is not one of the generated expressions. */
    static Boolean evaluate(String condition, Map<String, String> variables) {
        if (condition == null || variables == null
                || !variables.containsKey("exceptionTyp")) {
            return null;
        }
        // v1.3.13 templates use only exceptionTyp. Validate against the original
        // CSV variable before accepting; unrelated conditions still use legacy JEXL.
        Matcher single = SINGLE_CONDITION.matcher(condition);
        if (single.matches() && variables.containsKey("exceptionTyp")
                && matchesResolvedValue(single.group(1), variables.get("exceptionTyp"))) {
            boolean typeIsNull = isNull(variables.get("exceptionTyp"));
            return "==".equals(single.group(2)) ? typeIsNull : !typeIsNull;
        }
        Matcher matcher = GENERATED_CONDITION.matcher(condition);
        if (!matcher.matches() || !variables.containsKey("exceptionReview")) {
            return null;
        }
        // Confirm the operands really originate from the expected CSV columns.
        if (!matchesResolvedValue(matcher.group(1), variables.get("exceptionTyp"))
                || !matchesResolvedValue(matcher.group(3), variables.get("exceptionReview"))) {
            return null;
        }
        boolean typeIsNull = isNull(variables.get("exceptionTyp"));
        boolean reviewIsNull = isNull(variables.get("exceptionReview"));
        boolean typeMatches = "==".equals(matcher.group(2)) ? typeIsNull : !typeIsNull;
        boolean reviewMatches = "==".equals(matcher.group(4)) ? reviewIsNull : !reviewIsNull;
        return typeMatches && reviewMatches;
    }

    private static boolean matchesResolvedValue(String resolved, String raw) {
        if (isNull(raw)) {
            // Both forms are supported, but processString normally emits {NULL}.
            return "{NULL}".equalsIgnoreCase(resolved)
                    || "NULL".equalsIgnoreCase(resolved);
        }
        return resolved.equals(raw);
    }

    private static boolean isNull(String value) {
        return value == null || value.isEmpty()
                || "NULL".equalsIgnoreCase(value)
                || "{NULL}".equalsIgnoreCase(value);
    }
}
